const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('latin1');

// Find all CREATE TABLE statements
const matches = str.match(/CREATE TABLE[^)]+\)/gi);
if (matches) {
  const tableNames = matches.map(m => {
    const match = m.match(/CREATE TABLE\s+\"?(\w+)\"?/i);
    return match ? match[1] : 'unknown';
  });
  console.log('All tables:', [...new Set(tableNames)].join(', '));
}
"

