node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the next cart_item_id
const maxItem = db.prepare(\"SELECT cart_item_id FROM cart_items ORDER BY cart_item_id DESC LIMIT 1\").get();
console.log('Last cart_item_id:', maxItem);

// Extract number and increment
const lastNum = parseInt(maxItem.cart_item_id.replace('CI-', ''), 10);
const newId = 'CI-' + String(lastNum + 1).padStart(4, '0');
console.log('New cart_item_id:', newId);

// Insert the cart item
db.prepare(\"INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id) VALUES (?, ?, ?, ?, ?, ?, ?)\")
  .run(newId, 'CART-user_1d80ab67', 'user_1d80ab67', 'PROD-73FAB4', 1, 0, null);

// Update the cart totals and item_ids_json
db.prepare(\"UPDATE carts SET subtotal = 88, total = 88, item_ids_json = ? WHERE cart_id = 'CART-user_1d80ab67'\")
  .run(JSON.stringify([newId]));

// Verify
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_1d80ab67'\").get();
const items = db.prepare(\"SELECT * FROM cart_items WHERE cart_id = 'CART-user_1d80ab67'\").all();
console.log('\n=== UPDATED CART ===');
console.log(JSON.stringify(cart, null, 2));
console.log('\n=== CART ITEMS ===');
items.forEach(i => console.log(JSON.stringify(i, null, 2)));
"

